def main():
    p = argparse.ArgumentParser(
        description="Refine cell masks into polylines with MobileSAM"
    )
    p.add_argument(
        "--weights_path", type=str, required=True, help="Path to MobileSAM weights"
    )
    p.add_argument(
        "--output_path", type=str, required=True, help="Output folder (or .csv path)"
    )
    p.add_argument("--rgb_path", type=str, required=True, help="Path to RGB image")
    p.add_argument("--csv_path", type=str, required=True, help="Path to metadata csv")
